import test from "node:test";
import assert from "node:assert/strict";
import {apply, planner} from "./replay.mjs";

const catalog = () => ({default: 5, studios: new Map([["orchid", 8], ["iris", 2]])});
const book = (id, tenant = "orchid", units = 7, day = "2025-04-02", service = "studio") =>
  ({action: "book", service, id, tenant, units, day});
const renew = (previous, id, extra = {}) =>
  ({action: "renew", service: "studio", previous, id, day: "2025-05-02", ...extra});

test("Studio allocations, fallback and tenant/day accounting", () => {
  const dispatch = planner(catalog());
  assert.deepEqual(dispatch(book("first")), {status: "booked", id: "first", remaining: 1});
  assert.deepEqual(dispatch(book("overflow", "orchid", 2)), {status: "full", id: "overflow", remaining: 1});
  assert.equal(dispatch(book("last", "orchid", 1)).remaining, 0);
  assert.equal(dispatch(book("next-day", "orchid", 8, "2025-04-03")).status, "booked");
  assert.equal(dispatch(book("unknown", "lily", 6)).status, "full");
  assert.equal(dispatch(book("fallback", "lily", 5)).status, "booked");
  assert.equal(dispatch(book("lower", "iris", 3)).status, "full");
  assert.equal(dispatch(book("archive", "orchid", 6, "2025-04-02", "archive")).status, "full");
});

test("Studio replay, conflicts, cancellation and imports retain ledger semantics", () => {
  const config = catalog();
  const dispatch = planner(config);
  const request = book("first");
  dispatch(request);
  config.studios.set("orchid", 2);
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units: 1}).status, "conflict");
  assert.equal(dispatch({action: "summary", service: "studio"}).events.length, 1);
  assert.equal(dispatch({action: "cancel", service: "studio", id: "first"}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({action: "cancel", service: "studio", id: "first"}).status, "replay");
  assert.equal(dispatch(book("freed", "orchid", 2)).status, "booked");
  assert.equal(dispatch({...book("backfill", "orchid", 10), action: "import"}).status, "imported");
  assert.deepEqual(dispatch(book("over-import", "orchid", 1)), {status: "full", id: "over-import", remaining: 0});
  assert.deepEqual(apply(dispatch, book("invalid", "orchid", 0)), {status: "invalid", field: "units"});
});

test("monthly Studio renewals use the same allocation and ledger semantics", () => {
  const dispatch = planner(catalog());
  dispatch(book("prior"));
  const next = renew("prior", "next");
  assert.deepEqual(dispatch(next), {status: "booked", id: "next", remaining: 1});
  assert.equal(dispatch(next).status, "replay");
  assert.equal(dispatch({...next, units: 6}).status, "conflict");
  assert.equal(dispatch(renew("prior", "overflow", {units: 2})).status, "full");
  dispatch({action: "cancel", service: "studio", id: "next"});
  assert.equal(dispatch(next).status, "cancelled");
  assert.equal(dispatch(renew("prior", "replacement", {units: 8})).status, "booked");
  assert.equal(dispatch(renew("next", "inactive")).status, "missing");
  assert.equal(dispatch(renew("absent", "missing")).status, "missing");
  assert.deepEqual(apply(dispatch, renew("prior", "bad", {day: "2025-02-30"})), {status: "invalid", field: "day"});
  dispatch(book("lower-prior", "iris", 2));
  assert.equal(dispatch(renew("lower-prior", "lower-next", {units: 3})).status, "full");
  dispatch(book("default-prior", "lily", 5));
  assert.equal(dispatch(renew("default-prior", "default-next", {units: 6})).status, "full");
  dispatch(book("archive-prior", "orchid", 5, "2025-04-02", "archive"));
  assert.equal(dispatch(renew("archive-prior", "archive-next", {service: "archive", units: 6})).status, "full");
});
